def build_S(row0):
    n=len(row0)
    p=1
    for p in range(1,n+1):
        if all(row0[c]==-1 or row0[c]==row0[c%p] for c in range(n) if c%p!=c or True) and all(row0[c]==-1 or c>=p or row0[c]!=0 for c in range(n)):
            pass
    # simpler: find smallest p such that every nonzero cell equals a nonzero cell at c-p
    z=[v for v in row0]
    for p in range(1,n):
        ok=True
        for c in range(n):
            if z[c]!=0:
                # must equal some nonzero at c-p or c+p within period
                if c-p>=0 and z[c-p]!=0 and z[c-p]!=z[c]: ok=False;break
                if c+p<n and z[c+p]!=0 and z[c+p]!=z[c]: ok=False;break
        if ok:
            # check we can fill zeros consistently
            S=z[:]
            for c in range(n):
                if S[c]==0:
                    S[c]=S[c-p] if c-p>=0 else S[c+p]
            return S
